"""Permutation test CPU fixture."""

import numpy as np
import cupy as cp


def run(n_permutations: int = 1000) -> float:
    group_a = cp.array([1.0, 2.0, 3.0, 4.0])
    group_b = cp.array([2.0, 3.0, 4.0, 5.0])
    observed = cp.mean(group_b) - cp.mean(group_a)
    combined = cp.array([1.0, 2.0, 3.0, 4.0, 2.0, 3.0, 4.0, 5.0])
    count = 0
    for _ in range(n_permutations):
        order = cp.random.uniform(size=len(combined))
        permuted = combined[np.argsort(order)]
        diff = cp.mean(permuted[4:]) - cp.mean(permuted[:4])
        count += diff >= observed
    return float(count / n_permutations)


if __name__ == "__main__":
    print(run())
